"""Partition dates and calendar periods for coordination (ADR #130 §1, §4).

Every run date and every asset fact is put on one date line: the start of the
partition it names. A weekly key ``2024-W03`` is its Monday, a monthly key
``2024-01`` is the 1st, an hourly key is its day, a daily key is itself.
"""

from __future__ import annotations

from datetime import date, timedelta

from .partitions import partition_start

#: Facts of these granularities serve only the consumer's own date.
EXACT_GRANULARITIES = frozenset({"hourly", "daily"})
#: Facts of these granularities serve their own calendar period and the next one.
PERIOD_GRANULARITIES = frozenset({"weekly", "monthly"})


def partition_date(key: str) -> date:
    """Normalised date of a partition key of any granularity."""
    return partition_start(key).date()


def in_current_or_previous_period(fact: date, target: date, granularity: str) -> bool:
    """True when ``fact`` lies in ``target``'s period or in the period before.

    Periods are calendar periods: ISO weeks for ``weekly``, months for
    ``monthly``. Fixed day counts would leave dates that no fact can satisfy
    for irregular schedules such as "first Monday of the month".
    """
    if granularity == "weekly":
        target_week = target - timedelta(days=target.weekday())
        fact_week = fact - timedelta(days=fact.weekday())
        return target_week - timedelta(days=7) <= fact_week <= target_week
    if granularity == "monthly":
        target_month = target.year * 12 + target.month - 1
        fact_month = fact.year * 12 + fact.month - 1
        return target_month - 1 <= fact_month <= target_month
    raise ValueError(f"granularity {granularity!r} has no calendar period")


def oldest_useful_date(target: date) -> date:
    """Earliest partition date that can serve ``target`` under any granularity.

    The 1st of the previous month: a monthly fact from last month is the
    oldest fact rule B accepts, and it is never newer than a weekly fact from
    last week.
    """
    first_of_month = target.replace(day=1)
    return (first_of_month - timedelta(days=1)).replace(day=1)
